<template>
  <div class="vux-datetime">
    <!--
      The regression this file exists for: the literal used to be emitted as
      `"确定"`, which closed the double-quoted attribute and made the Vue
      template compiler drop the whole element.
    -->
    <x-picker
      :data-confirm-text="$t('confirm_text')"
      :data-cancel-text="$t('cancel_text')"
      @on-change="onChange"></x-picker>
  </div>
</template>

<script>
// Extension-less, like every component import inside vux: nothing on disk is
// named `../inline-desc`, which is what the resolver plugin exists for.
import InlineDesc from "../inline-desc";

export default {
  name: "datetime",
  components: { InlineDesc },
  methods: {
    onChange() {},
  },
};
</script>
